ALTER TABLE "wallet_entries" DROP CONSTRAINT "wallet_entries_shape_check";--> statement-breakpoint
ALTER TABLE "wallet_entries" ADD CONSTRAINT "wallet_entries_shape_check" CHECK (("wallet_entries"."entry_type" = 'grant' AND "wallet_entries"."credit_grant_id" IS NOT NULL AND "wallet_entries"."delta" > 0) OR ("wallet_entries"."entry_type" = 'spend' AND "wallet_entries"."credit_grant_id" IS NULL AND "wallet_entries"."delta" < 0) OR ("wallet_entries"."entry_type" = 'reversal' AND "wallet_entries"."credit_grant_id" IS NOT NULL AND "wallet_entries"."delta" < 0) OR ("wallet_entries"."entry_type" = 'correction' AND "wallet_entries"."delta" <> 0));